record.field:
line_model = env['x_hr.applicant_required_document_submission_request_line'].sudo()

action = False

for request in records.sudo():
    applicant = request.x_applicant_id
    checklist = request.x_checklist_id

    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Applicant missing',
                'message': 'Cannot generate request lines because the request is not linked to an applicant.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not checklist:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Checklist missing',
                'message': 'Cannot generate request lines because the request is not linked to an F-0003 checklist.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    target_lines = checklist.x_line_ids.filtered(
        lambda line: line.x_required
        and line.x_public_request_enabled
        and line.x_status in ('missing', 'rejected', 'resubmission_requested')
    ).sorted(key=lambda line: ((line.x_sequence or 0), line.id))

    if not target_lines:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'No requestable document lines',
                'message': 'No missing, rejected, or resubmission-requested public document lines were found for this checklist.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    target_line_ids = []

    for checklist_line in target_lines:
        target_line_ids.append(checklist_line.id)

        document_type = checklist_line.x_document_type_id
        document_code = checklist_line.x_document_code or (document_type.x_code if document_type else False)
        prefix = checklist_line.x_fillout_prefix or document_code

        if not prefix:
            continue

        existing = line_model.search([
            ('x_request_id', '=', request.id),
            ('x_checklist_line_id', '=', checklist_line.id),
        ], order='id desc', limit=1)

        values = {
            'x_request_id': request.id,
            'x_sequence': checklist_line.x_sequence or 0,
            'x_applicant_id': applicant.id,
            'x_checklist_id': checklist.id,
            'x_checklist_line_id': checklist_line.id,
            'x_document_type_id': document_type.id if document_type else False,
            'x_document_code': document_code,
            'x_fillout_prefix': prefix,
            'x_public_request_enabled': checklist_line.x_public_request_enabled,
            'x_requires_attachment': checklist_line.x_requires_attachment,
            'x_manual_review_expected': checklist_line.x_manual_review_expected,
            'x_structured_data_required': checklist_line.x_structured_data_required,
            'x_show_param_name': '%s_show' % prefix,
            'x_request_line_param_name': '%s_request_line_id' % prefix,
            'x_checklist_line_param_name': '%s_checklist_line_id' % prefix,
            'x_document_type_param_name': '%s_document_type_id' % prefix,
            'x_document_code_param_name': '%s_document_code' % prefix,
            'x_state': 'requested',
            'x_notes': checklist_line.x_notes or False,
        }

        values['x_name'] = '%s / %s' % (
            request.x_request_reference or request.x_name or ('Request %s' % request.id),
            checklist_line.x_document_name_en or checklist_line.x_document_name_ar or document_code,
        )

        if existing:
            existing.write(values)
        else:
            line_model.create(values)

    stale_lines = line_model.search([
        ('x_request_id', '=', request.id),
        ('x_checklist_line_id', 'not in', target_line_ids),
        ('x_state', '=', 'requested'),
    ])
    if stale_lines:
        stale_lines.write({
            'x_state': 'cancelled',
            'x_notes': 'Cancelled because the checklist line is no longer requestable.',
        })

    request_values = {
        'x_state': 'prepared',
        'x_requested_by_user_id': request.x_requested_by_user_id.id or env.user.id,
        'x_requested_on': request.x_requested_on or datetime.datetime.now(),
    }

    if not request.x_request_reference:
        request_values['x_request_reference'] = 'MCEP-HR-F-0003-REQ-%05d' % request.id

    if not request.x_name:
        request_values['x_name'] = '%s / F-0003 Request #%s / %s' % (
            applicant.partner_name or applicant.name or applicant.display_name,
            request.x_sequence or request.id,
            request_values.get('x_request_reference') or request.x_request_reference,
        )

    request.write(request_values)

    request.message_post(body='Generated %s required document request line(s).' % len(target_lines))
    checklist.message_post(body='Generated public submission request lines for request: %s.' % request.x_request_reference)

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
